fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let len = m.max(n);

    // If lengths are equal, just clone both
    if m == n {
        return (a, b);
    }

    // At this point, one length is 1, the other > 1 (given the assumption)
    // Identify which one is length 1
    if m == 1 {
        // a has length 1, broadcast it by repeating its only element
        let repeated_a = vec![a[0]; len];
        // b is longer, copy as is
        (repeated_a, b)
    } else {
        // b has length 1, broadcast it by repeating its only element
        let repeated_b = vec![b[0]; len];
        // a is longer, copy as is
        (a, repeated_b)
    }
}